90	   */
91	  emitDiagnostic(
92	    severity: 'info' | 'warning' | 'error',
93	    message: string,
94	    error?: unknown,
95	    serverName?: string,
96	  ) {
97	    // Capture error for later display if it's an error/warning
98	    if (severity === 'error' || severity === 'warning') {
99	      if (serverName) {
100	        this.lastErrors.set(serverName, message);
101	      }
102	    }
103	
104	    // Deduplicate
105	    const diagnosticKey = `${severity}:${message}`;
106	    const previousStatus = this.shownDiagnostics.get(diagnosticKey);
107	
108	    // If user has interacted, show verbosely unless already shown verbosely
109	    if (this.userInteractedWithMcp) {
110	      if (previousStatus === 'verbose') {
111	        debugLogger.debug(
112	          `Deduplicated verbose MCP diagnostic: ${diagnosticKey}`,
113	        );
114	        return;
115	      }
116	      this.shownDiagnostics.set(diagnosticKey, 'verbose');
117	      coreEvents.emitFeedback(severity, message, error);
118	      return;
119	    }
120	
121	    // In silent mode, if it has been shown at all, skip
122	    if (previousStatus) {
123	      debugLogger.debug(`Deduplicated silent MCP diagnostic: ${diagnosticKey}`);
124	      return;
125	    }
126	    this.shownDiagnostics.set(diagnosticKey, 'silent');
127	
128	    // Otherwise, be less annoying
129	    debugLogger.log(`[MCP ${severity}] ${message}`, error);
130	
131	    if (severity === 'error' || severity === 'warning') {
132	      if (!this.hintShown) {
133	        this.hintShown = true;
134	        coreEvents.emitFeedback(
135	          'info',
136	          'MCP issues detected. Run /mcp list for status.',
137	        );
138	      }
139	    }
140	  }
